package live.linghe.privateinput;

import android.app.Instrumentation;import android.os.Bundle;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;

public final class PersonalDataCheck extends Instrumentation {
 private File fixture;private int checks=0;
 public void onCreate(Bundle data){super.onCreate(data);start();}
 private void require(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 private interface Check{void run()throws Exception;}
 private void reject(Check action)throws Exception{boolean rejected=false;try{action.run();}catch(Exception expected){rejected=true;}require(rejected,"invalid edit rejected");}
 private PersonalLexicon store(String name){return new PersonalLexicon(new File(fixture,name));}
 private String asset(String name)throws Exception{try(InputStream in=getTargetContext().getAssets().open(name)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);return out.toString("UTF-8");}}
 private void remove(File file){if(file.isDirectory()){File[] all=file.listFiles();if(all!=null)for(File child:all)remove(child);}file.delete();}
 public void onStart(){Bundle result=new Bundle();try{
  fixture=new File(getTargetContext().getCacheDir(),"personal-check-"+System.nanoTime());require(fixture.mkdirs(),"isolated fixture");Set<String> syllables=new HashSet<>(Arrays.asList("ni","hao","mi","ling","he"));
  PersonalLexicon store=store("main");require(store.load().entries.isEmpty(),"new empty store");PersonalLexicon.Entry word=PersonalLexicon.Entry.create("word","拟好"," NI ' HAO ");PersonalLexicon.Snapshot initial=store.upsert(word,syllables);require(initial.entries.size()==1&&initial.entries.get(0).trigger.equals("ni hao"),"normalized roundtrip");require(store.load().entries.get(0).same(word),"persisted entry identity");checks++;
  PersonalLexicon.Entry other=PersonalLexicon.Entry.create("word","米好","mi hao");store.upsert(other,syllables);PersonalLexicon.Snapshot state=store.load();require(state.matches("64426",true).size()==2,"nine-key ambiguity");require(state.matches("ni'426",true).size()==1&&state.matches("ni'426",true).get(0).id.equals(word.id),"protected locked reading");require(state.matches("mi'hao'",true).get(0).id.equals(other.id),"multiple locked syllables");require(state.matches("644",true).isEmpty()&&state.matches("nih",false).isEmpty(),"explicit words exact only");checks++;
  PersonalLexicon.Entry phrase=PersonalLexicon.Entry.create("phrase","合成地址\n请先联系","DZ");state=store.upsert(phrase,null);require(state.matches("dz",false).get(0).text.contains("\n"),"multiline phrase");require(state.matches("39",true).size()==1&&state.matches("d'z'",true).isEmpty(),"phrase shortcut locked syllable exclusion");checks++;
  String before=state.encode();reject(()->store.upsert(PersonalLexicon.Entry.create("word","拟好","ni hao"),syllables));reject(()->store.upsert(PersonalLexicon.Entry.create("word","坏音","xxxx"),syllables));reject(()->store.upsert(PersonalLexicon.Entry.create("phrase","bad\0data","bb"),null));require(store.load().encode().equals(before),"invalid/duplicate edits atomic");checks++;
  state=store.remove(word.id);require(state.matches("nihao",false).isEmpty()&&state.removed().size()==1,"persistent deletion tombstone");store.merge(before);require(store.load().matches("nihao",false).isEmpty(),"stale snapshot cannot revive");store.upsert(word,syllables);require(store.load().matches("nihao",false).size()==1,"explicit restoration advances revision");checks++;
  PersonalLexicon left=store("left"),right=store("right");PersonalLexicon.Entry conflict=PersonalLexicon.Entry.create("phrase","原短语","cl");String base=left.upsert(conflict,null).encode();right.merge(base);PersonalLexicon.Entry edited=new PersonalLexicon.Entry(conflict.id,"phrase","离线编辑","cl");right.upsert(edited,null);left.remove(conflict.id);String deleted=left.load().encode(),updated=right.load().encode();left.merge(updated);right.merge(deleted);require(left.load().entries.isEmpty()&&right.load().entries.isEmpty(),"concurrent edit/delete delete wins on both peers");right.upsert(edited,null);left.merge(right.load().encode());require(left.load().entries.get(0).text.equals("离线编辑"),"explicit later restore converges");checks++;
  PersonalLexicon alias=store("alias");PersonalLexicon.Entry first=PersonalLexicon.Entry.create("phrase","相同短语","xx"),second=PersonalLexicon.Entry.create("phrase","相同短语","xx");PersonalLexicon remote=store("alias-remote");String remoteOld=remote.upsert(second,null).encode();alias.upsert(first,null);alias.merge(remoteOld);require(alias.load().entries.size()==1,"sync aliases materialize once");String visibleID=alias.load().entries.get(0).id;alias.remove(visibleID);alias.merge(remoteOld);require(alias.load().entries.isEmpty(),"hidden aliases retired on deletion");checks++;
  PersonalLexicon damaged=store("damaged");damaged.upsert(word,syllables);File file=new File(fixture,"damaged/personal-lexicon-v1.json");byte[] bad="broken archive".getBytes(StandardCharsets.UTF_8);Files.write(file.toPath(),bad);reject(damaged::load);reject(()->damaged.upsert(other,syllables));require(Arrays.equals(Files.readAllBytes(file.toPath()),bad),"damaged file never overwritten");checks++;
  reject(()->PersonalLexicon.decode(new String(new char[PersonalLexicon.MAX_BYTES+1]).replace('\0','a')));JSONObject wrong=new JSONObject(before);wrong.put("version","1");reject(()->PersonalLexicon.decode(wrong.toString()));JSONObject nullEntry=new JSONObject(before);nullEntry.getJSONArray("entries").getJSONObject(0).put("text",JSONObject.NULL);reject(()->PersonalLexicon.decode(nullEntry.toString()));reject(()->store.upsert(PersonalLexicon.Entry.create("phrase","\u00a0","nb"),null));reject(()->store.upsert(PersonalLexicon.Entry.create("phrase","bad\u202Etext","bd"),null));checks++;
  String fixtureJSON=asset("personal-lexicon-fixture-v1.json");PersonalLexicon.Snapshot compatible=PersonalLexicon.decode(fixtureJSON);require(compatible.entries.size()==3&&compatible.removed().size()==1,"Apple protocol fixture decoded");require(compatible.matches("64426",true).size()==2&&compatible.matches("ni'426",true).get(0).text.equals("拟好"),"Apple fixture matching semantics");File exported=new File(getTargetContext().getExternalFilesDir(null),"personal-fixture-roundtrip.json");Files.write(exported.toPath(),compatible.encode().getBytes(StandardCharsets.UTF_8));result.putString("fixtureExport",exported.getAbsolutePath());checks++;
  JSONObject equalRevision=new JSONObject(before);JSONObject rows=equalRevision.getJSONObject("synchronization").getJSONObject("records");rows.getJSONObject(word.id).getJSONObject("entry").put("text","矛盾内容");equalRevision.getJSONArray("entries").getJSONObject(0).put("text","矛盾内容");PersonalLexicon equalStore=store("equal-revision");equalStore.merge(before);String original=equalStore.load().encode();reject(()->equalStore.merge(equalRevision.toString()));require(equalStore.load().encode().equals(original),"equal revision conflict rejected atomically");checks++;
  PersonalLexicon unchanged=store("unchanged");String current=unchanged.upsert(word,syllables).encode();File currentFile=new File(fixture,"unchanged/personal-lexicon-v1.json");long timestamp=1700000000000L;Files.setLastModifiedTime(currentFile.toPath(),java.nio.file.attribute.FileTime.fromMillis(timestamp));unchanged.merge(current);unchanged.upsert(word,syllables);require(currentFile.lastModified()==timestamp,"unchanged merge/save do not rewrite the file");checks++;
  JSONObject lower=new JSONObject(before),upper=new JSONObject(before);for(JSONObject value:new JSONObject[]{lower,upper}){String device=value==lower?"aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa":"AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA";String text=value==lower?"小写设备排序":"大写设备排序";JSONObject row=value.getJSONObject("synchronization").getJSONObject("records").getJSONObject(word.id);row.getJSONObject("revision").put("device",device);row.getJSONObject("entry").put("text",text);value.getJSONArray("entries").getJSONObject(0).put("text",text);}PersonalLexicon casing=store("device-casing");casing.merge(upper.toString());casing.merge(lower.toString());require(casing.load().entries.get(0).text.equals("小写设备排序"),"logical device strings preserve Apple lexical ordering");checks++;
  AtomicReference<Throwable> uiError=new AtomicReference<>();runOnMainSync(()->{try{Context c=new ContextThemeWrapper(getTargetContext(),android.R.style.Theme_Material_Light);ArrayList<CandidateViews.Item> items=new ArrayList<>();for(int i=0;i<5000;i++)items.add(new CandidateViews.Item(new String[]{String.valueOf(i),"候选"+i,"hou xuan"}));AtomicReference<String> selected=new AtomicReference<>();AtomicInteger requested=new AtomicInteger();CandidateViews.Strip strip=new CandidateViews.Strip(c,item->selected.set(item.id),requested::incrementAndGet);strip.update(items,true);int width=Ui.dp(c,400),height=Ui.dp(c,42);strip.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));strip.layout(0,0,width,height);FrameLayout content=(FrameLayout)strip.getChildAt(0);LinearLayout visible=(LinearLayout)content.getChildAt(0);require(visible.getChildCount()>0&&visible.getChildCount()<80,"5000 candidates retain only viewport buttons");
   require(content.getMeasuredHeight()>0&&visible.getMeasuredHeight()>0&&visible.getChildAt(0).getMeasuredHeight()>0,"candidate content and buttons have visible measured height");
   android.graphics.Rect cell=new android.graphics.Rect();require(visible.getChildAt(0).getLocalVisibleRect(cell)&&cell.height()>Ui.dp(c,30),"candidate has visible viewport area");
   android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(bitmap);canvas.drawColor(android.graphics.Color.WHITE);strip.draw(canvas);int ink=0;for(int y=0;y<height;y++)for(int x=0;x<Math.min(width,Ui.dp(c,100));x++){int pixel=bitmap.getPixel(x,y);if(android.graphics.Color.red(pixel)<160&&android.graphics.Color.green(pixel)<160&&android.graphics.Color.blue(pixel)<160)ink++;}Button diagnostic=(Button)visible.getChildAt(0);require(diagnostic.getLayout()!=null&&diagnostic.getLayout().getEllipsisCount(0)==0,"short candidate must remain fully readable; width="+diagnostic.getWidth()+" paint="+diagnostic.getPaint().getTextSize()+" padding="+diagnostic.getCompoundPaddingLeft()+","+diagnostic.getCompoundPaddingRight());require(diagnostic.getLayout()!=null&&diagnostic.getLayout().getWidth()<=diagnostic.getMeasuredWidth(),"text layout stays within actual candidate cell width");
   File image=new File(getTargetContext().getExternalFilesDir(null),"candidate-component9.png");try(FileOutputStream imageOut=new FileOutputStream(image)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,imageOut);}catch(IOException error){throw new RuntimeException(error);}
   require(ink>20,"candidate text ink="+ink+" strip="+strip.getWidth()+"x"+strip.getHeight()+" scroll="+strip.getScrollX()+" content="+content.getWidth()+"x"+content.getHeight()+" row="+visible.getWidth()+"x"+visible.getHeight()+" first="+diagnostic.getWidth()+"x"+diagnostic.getHeight()+" at="+diagnostic.getLeft()+","+diagnostic.getTop()+" text="+diagnostic.getText()+" color="+diagnostic.getCurrentTextColor()+" layout="+(diagnostic.getLayout()==null?"null":diagnostic.getLayout().getWidth()+"/"+diagnostic.getLayout().getHeight()));bitmap.recycle();strip.scrollTo(content.getMeasuredWidth()/2,0);require(visible.getChildCount()<80,"scrolling reuses bounded buttons");visible.getChildAt(0).performClick();require(Integer.parseInt(selected.get())>96,"recycled click retains real candidate ID beyond old limit: id="+selected.get()+", scroll="+strip.getScrollX()+", width="+content.getMeasuredWidth());strip.scrollTo(content.getMeasuredWidth(),0);require(requested.get()>0,"end scrolling requests continuation");CandidateViews.Expanded expanded=new CandidateViews.Expanded(c,item->selected.set(item.id),()->{});expanded.update(items);int eh=Ui.dp(c,280);expanded.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(eh,View.MeasureSpec.EXACTLY));expanded.layout(0,0,width,eh);require(expanded.getChildCount()<20,"expanded list recycles rows");View recycled=expanded.getAdapter().getView(100,expanded.getChildAt(0),expanded);((LinearLayout)recycled).getChildAt(0).performClick();require(Integer.parseInt(selected.get())>96,"expanded recycled row selects intended absolute item");}catch(Throwable failure){uiError.set(failure);}});if(uiError.get()!=null)throw new AssertionError("native candidate viewport: "+uiError.get().getMessage());checks++;
  result.putString("result","Passed");result.putInt("checks",checks);result.putBoolean("realUserDataTouched",false);result.putBoolean("visibleSystemGestureAcceptance",false);
 }catch(Throwable error){result.putString("result","Failed");result.putInt("checksCompleted",checks);result.putString("error",error.getClass().getSimpleName()+": "+error.getMessage());}
 finally{if(fixture!=null)remove(fixture);}finish("Passed".equals(result.getString("result"))?-1:0,result);
 }
}
